#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* 找零钱问题: 贪心(每次取最大面值) vs 动态规划最优
   演示贪心并不总是正确: 面值 1 3 4 找 6 元, 贪心 4+1+1 共 3 枚, 最优 3+3 共 2 枚
   输入: k S (面值个数 金额), 之后 k 个面值(可无序, 约定含 1)
   输出: 贪心与最优的硬币数 */
int cmp(const void *a, const void *b) { return *(int *)a - *(int *)b; }

int greedy(int c[], int k, int S) {
    int cnt = 0;
    for (int i = k - 1; i >= 0 && S > 0; i--)   /* 从大到小尽量多取 */
        cnt += S / c[i], S %= c[i];
    return cnt;
}

int optimal(int c[], int k, int S) {
    int dp[10005];
    memset(dp, 0x3f, sizeof(dp));               /* 初始化为无穷大 */
    dp[0] = 0;
    for (int s = 1; s <= S; s++)
        for (int i = 0; i < k; i++)
            if (s >= c[i] && dp[s - c[i]] + 1 < dp[s])
                dp[s] = dp[s - c[i]] + 1;
    return dp[S];
}

int main(void) {
    int k, S, c[20];
    printf("输入面值个数 k 与金额 S: ");
    if (scanf("%d %d", &k, &S) != 2 || k < 1 || S < 0 || S > 10000) {
        printf("输入无效!\n"); return 1;
    }
    printf("输入 %d 个面值: ", k);
    for (int i = 0; i < k; i++) scanf("%d", &c[i]);
    qsort(c, k, sizeof(int), cmp);
    int g = greedy(c, k, S), o = optimal(c, k, S);
    printf("贪心(每次取最大面值): %d 枚\n", g);
    printf("最优(动态规划):       %d 枚\n", o);
    if (o < g) printf("结论: 贪心失败! 局部最优不等于全局最优。\n");
    else       printf("结论: 本例贪心恰好最优。\n");
    return 0;
}

