#include <stdio.h>
#include <stdlib.h>

/* 活动选择: 按结束时间排序, 贪心选择最早结束的相容活动
   输入: n, 之后 n 对 s f (开始时间 结束时间)
   输出: 选出的相容活动与最大活动数
   示例: 5 / 1 3 2 5 4 7 1 8 5 9 -> 选出 [1,3) [4,7), 共 2 个 */
typedef struct { int s, f; } Act;

int cmp(const void *a, const void *b) {
    Act *x = (Act *)a, *y = (Act *)b;
    return x->f - y->f;                 /* 关键: 按结束时间升序 */
}

int main(void) {
    int n; Act a[100];
    printf("输入活动个数 n: ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个活动的开始与结束时间 s f: ", n);
    for (int i = 0; i < n; i++) scanf("%d %d", &a[i].s, &a[i].f);
    qsort(a, n, sizeof(Act), cmp);
    int last = -1, cnt = 0;
    printf("贪心选择的相容活动: ");
    for (int i = 0; i < n; i++)
        if (a[i].s >= last) {           /* 相容: 开始时间不小于上次结束时间 */
            printf("[%d, %d) ", a[i].s, a[i].f);
            last = a[i].f;
            cnt++;
        }
    printf("\n最大相容活动数 = %d\n", cnt);
    return 0;
}

#include <stdio.h>

/* 霍夫曼编码: 最小堆每次合并权最小的两棵子树, 求最优前缀码的总编码长度
   输入: n, 之后 n 个字符频率
   输出: 合并过程与最小总编码长度(WPL)
   示例: 6 / 5 9 12 13 16 45 -> WPL = 224 (内部结点权值之和) */
#define MAXN 200
long long heap[MAXN];
int hsize;

void push(long long x) {                        /* 小根堆插入(上滤) */
    int i = hsize++;
    heap[i] = x;
    while (i > 0 && heap[(i - 1) / 2] > heap[i]) {
        long long t = heap[i]; heap[i] = heap[(i - 1) / 2]; heap[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
}

long long pop(void) {                           /* 小根堆取出最小(下滤) */
    long long r = heap[0];
    heap[0] = heap[--hsize];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, m = i;
        if (l < hsize && heap[l] < heap[m]) m = l;
        if (l + 1 < hsize && heap[l + 1] < heap[m]) m = l + 1;
        if (m == i) break;
        long long t = heap[i]; heap[i] = heap[m]; heap[m] = t;
        i = m;
    }
    return r;
}

int main(void) {
    int n;
    printf("输入字符个数 n: ");
    if (scanf("%d", &n) != 1 || n < 2 || n > 100) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个频率: ", n);
    for (int i = 0; i < n; i++) { long long f; scanf("%lld", &f); push(f); }
    long long wpl = 0;
    printf("合并过程: ");
    while (hsize > 1) {
        long long a = pop(), b = pop();         /* 每次取最小的两棵 */
        long long z = a + b;
        printf("(%lld+%lld=%lld) ", a, b, z);
        wpl += z;                               /* WPL = 内部结点权值之和 */
        push(z);
    }
    printf("\n最小总编码长度 WPL = %lld\n", wpl);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* 区间选点: 用最少的点覆盖所有闭区间
   贪心: 按右端点升序, 每遇到未覆盖的区间就在其右端点放一个点
   输入: n, 之后 n 对 l r
   输出: 放置的点与最少点数
   示例: 5 / 1 4 2 3 3 5 6 8 5 7 -> 点 3 7, 共 2 个 */
typedef struct { int l, r; } Seg;

int cmp(const void *a, const void *b) {
    Seg *x = (Seg *)a, *y = (Seg *)b;
    return x->r - y->r;                 /* 关键: 按右端点升序 */
}

int main(void) {
    int n; Seg s[100];
    printf("输入区间个数 n: ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) { printf("输入无效!\n"); return 1; }
    printf("输入 %d 个闭区间 l r: ", n);
    for (int i = 0; i < n; i++) scanf("%d %d", &s[i].l, &s[i].r);
    qsort(s, n, sizeof(Seg), cmp);
    int cnt = 0, last = -1000000000;
    printf("放置的点: ");
    for (int i = 0; i < n; i++)
        if (s[i].l > last) {            /* 当前区间未被覆盖, 在右端点放点 */
            printf("%d ", s[i].r);
            last = s[i].r;
            cnt++;
        }
    printf("\n最少点数 = %d\n", cnt);
    return 0;
}

#include <stdio.h>
#include <string.h>

/* Dijkstra 单源最短路(稠密图数组实现, O(n^2))
   贪心选择: 每轮取 S 外 d 值最小的顶点, 松弛其出边
   输入: n m s (顶点数 边数 源点), 之后 m 条无向边 u v w
   输出: s 到各顶点的最短路长度
   示例: 5 6 0 / 0 1 2 / 0 2 4 / 1 2 1 / 1 3 7 / 2 4 3 / 3 4 1
         -> s 到 0:0, 1:2, 2:3, 3:7, 4:6 */
#define MAXN 1000
#define INF 0x3f3f3f3f
int g[MAXN][MAXN], d[MAXN], vis[MAXN];

int main(void) {
    int n, m, s;
    printf("输入 n m s: ");
    if (scanf("%d %d %d", &n, &m, &s) != 3 || n < 1 || n > MAXN) {
        printf("输入无效!\n"); return 1;
    }
    memset(g, 0x3f, sizeof(g));
    for (int i = 0; i < n; i++) g[i][i] = 0;
    printf("输入 %d 条边 u v w(顶点从 0 编号):\n", m);
    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        if (w < g[u][v]) g[u][v] = w;
        if (w < g[v][u]) g[v][u] = w;           /* 无向图双向加边 */
    }
    memset(d, 0x3f, sizeof(d));
    memset(vis, 0, sizeof(vis));
    d[s] = 0;
    for (int it = 0; it < n; it++) {
        int u = -1;
        for (int v = 0; v < n; v++)             /* 贪心选择: S 外 d 最小 */
            if (!vis[v] && (u == -1 || d[v] < d[u])) u = v;
        if (u == -1 || d[u] == INF) break;      /* 剩余顶点不可达 */
        vis[u] = 1;
        for (int v = 0; v < n; v++)             /* 松弛 u 的出边 */
            if (!vis[v] && d[u] + g[u][v] < d[v])
                d[v] = d[u] + g[u][v];
    }
    for (int v = 0; v < n; v++) {
        if (d[v] == INF) printf("s 到 %d: 不可达\n", v);
        else printf("s 到 %d: %d\n", v, d[v]);
    }
    return 0;
}

