#include <stdio.h>
#include <stdlib.h>

/* 分数背包(贪心最优) vs 0-1 背包(贪心失败, DP 正确) 对比
   输入: n W, 之后 n 对 w v (重量 价值)
   输出: 分数背包贪心值 / 0-1 背包按单位价值贪心值 / 0-1 背包 DP 最优值
   示例: 3 50 / 10 60 20 100 30 120 -> 240.0 / 160 / 220 */
typedef struct { int w, v; double r; } Item;

int cmp(const void *a, const void *b) {
    Item *x = (Item *)a, *y = (Item *)b;
    if (y->r > x->r) return 1;
    if (y->r < x->r) return -1;
    return 0;
}

int main(void) {
    int n, W; Item it[100];
    printf("输入 n W: ");
    if (scanf("%d %d", &n, &W) != 2 || n < 1 || n > 100 || W < 1 || W > 10000) {
        printf("输入无效!\n"); return 1;
    }
    printf("输入 %d 个物品的重量与价值 w v: ", n);
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &it[i].w, &it[i].v);
        it[i].r = (double)it[i].v / it[i].w;    /* 单位价值 */
    }
    qsort(it, n, sizeof(Item), cmp);            /* 按单位价值降序 */
    /* 分数背包: 可分割, 最后一件装部分 */
    double frac = 0.0;
    int cap = W;
    for (int i = 0; i < n && cap > 0; i++) {
        if (it[i].w <= cap) { frac += it[i].v; cap -= it[i].w; }
        else { frac += it[i].r * cap; cap = 0; }
    }
    /* 0-1 背包: 同样按单位价值贪心(整件取) */
    int g01 = 0; cap = W;
    for (int i = 0; i < n && cap > 0; i++)
        if (it[i].w <= cap) { g01 += it[i].v; cap -= it[i].w; }
    /* 0-1 背包: 动态规划最优(容量倒序滚动数组) */
    int dp[10001] = {0};
    for (int i = 0; i < n; i++)
        for (int c = W; c >= it[i].w; c--)
            if (dp[c - it[i].w] + it[i].v > dp[c])
                dp[c] = dp[c - it[i].w] + it[i].v;
    printf("分数背包(贪心, 可分割)     = %.1f\n", frac);
    printf("0-1 背包(按单位价值贪心)   = %d\n", g01);
    printf("0-1 背包(动态规划最优)     = %d\n", dp[W]);
    if (dp[W] > g01) printf("结论: 0-1 背包贪心失败! 必须用动态规划。\n");
    return 0;
}
